[
  {
    "taskTypeId": "ROOT",
    "description": "Invisible root; its childTaskIds order the top-level sections",
    "createdBy": "seed",
    "isActionable": false,
    "metaSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "type": "object",
      "properties": {}
    }
  },
  {
    "taskTypeId": "SECTION",
    "description": "Top-level group",
    "createdBy": "seed",
    "isActionable": false,
    "metaSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "type": "object",
      "properties": {
        "description": {
          "type": "string"
        },
        "icon": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "description"
      ]
    }
  },
  {
    "taskTypeId": "TAB",
    "description": "Group of leaf tasks shown together",
    "createdBy": "seed",
    "isActionable": false,
    "metaSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "type": "object",
      "properties": {
        "description": {
          "type": "string"
        },
        "icon": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "description"
      ]
    }
  },
  {
    "taskTypeId": "TEXT",
    "description": "Free text. Answer: {textBox: {value}}",
    "createdBy": "seed",
    "isActionable": true,
    "metaSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "type": "object",
      "properties": {
        "description": {
          "type": "string"
        },
        "icon": {
          "type": [
            "string",
            "null"
          ]
        },
        "textBox": {
          "type": "object",
          "properties": {
            "required": {
              "type": "boolean"
            },
            "description": {
              "type": "string"
            },
            "errorMessage": {
              "type": "string"
            },
            "type": {
              "type": "string",
              "enum": [
                "ALPHANUMERIC",
                "ALPHABETIC",
                "NUMERIC"
              ]
            }
          }
        }
      },
      "required": [
        "description",
        "textBox"
      ]
    }
  },
  {
    "taskTypeId": "RADIO_BUTTON",
    "description": "Single choice. Answer: {radioButton: {option}}",
    "createdBy": "seed",
    "isActionable": true,
    "metaSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "type": "object",
      "properties": {
        "description": {
          "type": "string"
        },
        "icon": {
          "type": [
            "string",
            "null"
          ]
        },
        "radioButton": {
          "type": "object",
          "properties": {
            "required": {
              "type": "boolean"
            },
            "description": {
              "type": "string"
            },
            "errorMessage": {
              "type": "string"
            },
            "options": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "minItems": 1
            }
          }
        }
      },
      "required": [
        "description",
        "radioButton"
      ]
    }
  },
  {
    "taskTypeId": "DROPDOWN",
    "description": "Single choice from a list. Answer: {dropdown: {option}}",
    "createdBy": "seed",
    "isActionable": true,
    "metaSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "type": "object",
      "properties": {
        "description": {
          "type": "string"
        },
        "icon": {
          "type": [
            "string",
            "null"
          ]
        },
        "dropdown": {
          "type": "object",
          "properties": {
            "required": {
              "type": "boolean"
            },
            "description": {
              "type": "string"
            },
            "errorMessage": {
              "type": "string"
            },
            "options": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "minItems": 1
            }
          }
        }
      },
      "required": [
        "description",
        "dropdown"
      ]
    }
  },
  {
    "taskTypeId": "CHECKBOX",
    "description": "One or more ticks. Answer: {checkbox: [{option}]}",
    "createdBy": "seed",
    "isActionable": true,
    "metaSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "type": "object",
      "properties": {
        "description": {
          "type": "string"
        },
        "icon": {
          "type": [
            "string",
            "null"
          ]
        },
        "checkbox": {
          "type": "object",
          "properties": {
            "required": {
              "type": "boolean"
            },
            "description": {
              "type": "string"
            },
            "errorMessage": {
              "type": "string"
            },
            "options": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "minItems": 1
            }
          }
        }
      },
      "required": [
        "description",
        "checkbox"
      ]
    }
  },
  {
    "taskTypeId": "IMAGE",
    "description": "Photo. Answer: {image: [{path, hashKey, timestamp}]}",
    "createdBy": "seed",
    "isActionable": true,
    "metaSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "type": "object",
      "properties": {
        "description": {
          "type": "string"
        },
        "icon": {
          "type": [
            "string",
            "null"
          ]
        },
        "image": {
          "type": "object",
          "properties": {
            "required": {
              "type": "boolean"
            },
            "description": {
              "type": "string"
            },
            "errorMessage": {
              "type": "string"
            },
            "options": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "object",
                "required": [
                  "hashKey"
                ],
                "properties": {
                  "hashKey": {
                    "type": "string"
                  },
                  "description": {
                    "type": "string"
                  },
                  "required": {
                    "type": "boolean"
                  },
                  "sideEffectBeans": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    }
                  }
                }
              }
            }
          }
        }
      },
      "required": [
        "description",
        "image"
      ]
    }
  }
]

[
  {
    "taskId": "root",
    "taskType": "ROOT",
    "parentTaskId": null,
    "childTaskIds": [
      "intro"
    ],
    "meta": {}
  },
  {
    "taskId": "intro",
    "taskType": "SECTION",
    "parentTaskId": "root",
    "childTaskIds": [
      "intro_tab"
    ],
    "meta": {
      "description": "Intro"
    }
  },
  {
    "taskId": "intro_tab",
    "taskType": "TAB",
    "parentTaskId": "intro",
    "childTaskIds": [
      "nickname",
      "agree"
    ],
    "meta": {
      "description": "Basics"
    }
  },
  {
    "taskId": "nickname",
    "taskType": "TEXT",
    "parentTaskId": "intro_tab",
    "childTaskIds": [],
    "meta": {
      "description": "Nickname",
      "textBox": {
        "required": true,
        "description": "What should we call you?",
        "type": "ALPHANUMERIC"
      }
    }
  },
  {
    "taskId": "agree",
    "taskType": "RADIO_BUTTON",
    "parentTaskId": "intro_tab",
    "childTaskIds": [],
    "meta": {
      "description": "Ready to start?",
      "radioButton": {
        "required": true,
        "options": [
          "Yes",
          "No"
        ]
      }
    }
  }
]
